// Embeds the app icon and version info into the Windows executable (shown in Explorer, the taskbar,
// the tray and the window title bar). The icon is generated by assets/make-icon.ps1.
fn main() {
    #[cfg(windows)]
    {
        let mut res = winresource::WindowsResource::new();
        res.set_icon("assets/icon.ico"); // resource id 1, loaded by src/tray.rs
        res.set("ProductName", "terminal-tunnel");
        res.set("FileDescription", "Remote terminal for a phone browser (end-to-end encrypted)");
        if let Err(e) = res.compile() {
            // Never fail the build over a missing resource compiler; the app just has no icon.
            println!("cargo:warning=could not embed the icon: {e}");
        }
    }
}
